/**
 * Feature: the additional configurations of an identity are returned by the Identity REST API v2 to a caller without
 * kura.admin only if the caller is allowed to manage that identity, consistently with the rules applied to updates.
 */
public class IdentityRestServiceV2AdditionalConfigurationsVisibilityTest {

    private static final String ADMIN_PERMISSION = "kura.admin";
    private static final String IDENTITY_PERMISSION = "rest.identity";
    private static final String HELD_PERMISSION = "rest.network.status";
    private static final String NOT_HELD_PERMISSION = "rest.command";
    private static final String LEGACY_ARGUMENT = "-kura.rest.identity.legacyIdentityManagement";

    private static final String MANAGER = "manager";
    private static final String MANAGEABLE = "manageable";
    private static final String MORE_PRIVILEGED = "morePrivileged";
    private static final String ADMIN = "admin";

    private static final String EXTENSION_PID = "test.identity.extension";

    private final InMemoryUserAdmin userAdmin = new InMemoryUserAdmin();
    private final IdentityService identityService = this.userAdmin.identityService();
    private final List<IdentityConfiguration> identities = new ArrayList<>();
    private final IdentityRestServiceV2 service = new IdentityRestServiceV2();

    private String[] frameworkArguments = new String[0];
    private ContainerRequestContext requestContext;
    private Map<String, IdentityConfigurationDTO> result;

    /*
     * Scenarios
     */

    @Test
    public void nonAdminSeesAdditionalConfigurationsOfManageableIdentities() throws KuraException {
        givenIdentity(MANAGER, IDENTITY_PERMISSION, HELD_PERMISSION);
        givenIdentity(MANAGEABLE, HELD_PERMISSION);
        givenRequestFrom(MANAGER);

        whenIdentitiesAreListed();

        thenAdditionalConfigurationsAreReturnedFor(MANAGEABLE);
        thenAdditionalConfigurationsAreReturnedFor(MANAGER);
    }

    @Test
    public void nonAdminDoesNotSeeAdditionalConfigurationsOfMorePrivilegedIdentities() throws KuraException {
        givenIdentity(MANAGER, IDENTITY_PERMISSION);
        givenIdentity(MORE_PRIVILEGED, NOT_HELD_PERMISSION);
        givenIdentity(ADMIN, ADMIN_PERMISSION);
        givenRequestFrom(MANAGER);

        whenIdentitiesAreListed();

        thenAdditionalConfigurationsAreNotReturnedFor(MORE_PRIVILEGED);
        thenAdditionalConfigurationsAreNotReturnedFor(ADMIN);
        thenPermissionsAreReturnedFor(MORE_PRIVILEGED, NOT_HELD_PERMISSION);
    }

    @Test
    public void nonAdminDoesNotSeeAdditionalConfigurationsOfMorePrivilegedIdentityByName() throws KuraException {
        givenIdentity(MANAGER, IDENTITY_PERMISSION);
        givenIdentity(ADMIN, ADMIN_PERMISSION);
        givenRequestFrom(MANAGER);

        whenIdentityIsRequestedByName(ADMIN);

        thenAdditionalConfigurationsAreNotReturnedFor(ADMIN);
        thenPermissionsAreReturnedFor(ADMIN, ADMIN_PERMISSION);
    }

    @Test
    public void nonAdminSeesAdditionalConfigurationsOfManageableIdentityByName() throws KuraException {
        givenIdentity(MANAGER, IDENTITY_PERMISSION, HELD_PERMISSION);
        givenIdentity(MANAGEABLE, HELD_PERMISSION);
        givenRequestFrom(MANAGER);

        whenIdentityIsRequestedByName(MANAGEABLE);

        thenAdditionalConfigurationsAreReturnedFor(MANAGEABLE);
    }

    @Test
    public void adminSeesAdditionalConfigurationsOfAllIdentities() throws KuraException {
        givenIdentity(ADMIN, ADMIN_PERMISSION);
        givenIdentity(MORE_PRIVILEGED, NOT_HELD_PERMISSION);
        givenRequestFrom(ADMIN);

        whenIdentitiesAreListed();

        thenAdditionalConfigurationsAreReturnedFor(ADMIN);
        thenAdditionalConfigurationsAreReturnedFor(MORE_PRIVILEGED);
    }

    @Test
    public void cloudRequestSeesAdditionalConfigurationsOfAllIdentities() throws KuraException {
        givenIdentity(ADMIN, ADMIN_PERMISSION);
        givenCloudRequest();

        whenIdentitiesAreListed();

        thenAdditionalConfigurationsAreReturnedFor(ADMIN);
    }

    @Test
    public void legacyArgumentRestoresVisibilityOfAllAdditionalConfigurations() throws KuraException {
        givenFrameworkArguments(LEGACY_ARGUMENT);
        givenIdentity(MANAGER, IDENTITY_PERMISSION);
        givenIdentity(ADMIN, ADMIN_PERMISSION);
        givenRequestFrom(MANAGER);

        whenIdentitiesAreListed();

        thenAdditionalConfigurationsAreReturnedFor(ADMIN);
    }

    /*
     * Steps
     */

    /*
     * Given
     */

    private void givenIdentity(final String name, final String... permissions) {
        this.userAdmin.addIdentity(name, permissions);

        final Map<String, Object> properties = new HashMap<>();
        properties.put("test.property", "value of " + name);
        final ComponentConfiguration extensionConfiguration = new ComponentConfigurationImpl(EXTENSION_PID, null,
                properties);

        final List<IdentityConfigurationComponent> components = new ArrayList<>();
        components.add(new AssignedPermissions(
                Arrays.stream(permissions).map(Permission::new).collect(Collectors.toSet())));
        components.add(new AdditionalConfigurations(Collections.singletonList(extensionConfiguration)));

        this.identities.add(new IdentityConfiguration(name, components));
    }

    private void givenRequestFrom(final String name) {
        this.requestContext = InMemoryUserAdmin.requestFrom(name);
    }

    private void givenCloudRequest() {
        this.requestContext = null;
    }

    private void givenFrameworkArguments(final String... arguments) {
        this.frameworkArguments = arguments;
    }

    /*
     * When
     */

    private void whenIdentitiesAreListed() throws KuraException {
        bindService();
        when(this.identityService.getIdentitiesConfiguration(any())).thenReturn(this.identities);

        this.result = this.service.getIdentities(this.requestContext).stream()
                .collect(Collectors.toMap(i -> i.getIdentity().getName(), i -> i));
    }

    private void whenIdentityIsRequestedByName(final String name) throws KuraException {
        bindService();
        for (final IdentityConfiguration identity : this.identities) {
            when(this.identityService.getIdentityConfiguration(eq(identity.getName()), any()))
                    .thenReturn(Optional.of(identity));
        }

        final IdentityConfigurationRequestDTO request = new IdentityConfigurationRequestDTO();
        request.setIdentity(new IdentityDTO(name));
        request.setConfigurationComponents(
                new HashSet<>(Arrays.asList("AdditionalConfigurations", "AssignedPermissions")));

        final IdentityConfigurationDTO identity = this.service.getIdentityByName(request, this.requestContext);
        this.result = Collections.singletonMap(name, identity);
    }

    /*
     * Then
     */

    private void thenAdditionalConfigurationsAreReturnedFor(final String name) {
        final IdentityConfigurationDTO identity = this.result.get(name);
        assertNotNull(name + " should be returned", identity);
        assertNotNull(name + " additional configurations should be returned", identity.getAdditionalConfigurations());
        assertEquals(1, identity.getAdditionalConfigurations().getConfigurations().size());
        assertEquals("value of " + name, identity.getAdditionalConfigurations().getConfigurations().iterator().next()
                .getProperties().get("test.property").getValue());
    }

    private void thenAdditionalConfigurationsAreNotReturnedFor(final String name) {
        final IdentityConfigurationDTO identity = this.result.get(name);
        assertNotNull(name + " should be returned", identity);
        assertNull(name + " additional configurations must not be returned", identity.getAdditionalConfigurations());
    }

    private void thenPermissionsAreReturnedFor(final String name, final String... permissions) {
        final IdentityConfigurationDTO identity = this.result.get(name);
        assertNotNull(name + " permissions should be returned", identity.getPermissionConfiguration());
        assertEquals(new HashSet<>(Arrays.asList(permissions)),
                identity.getPermissionConfiguration().getPermissions().stream().map(p -> p.getName())
                        .collect(Collectors.toSet()));
    }

    /*
     * Utilities
     */

    private void bindService() {
        final EnvironmentInfo environmentInfo = mock(EnvironmentInfo.class);
        when(environmentInfo.getNonFrameworkArgs()).thenReturn(this.frameworkArguments);

        this.service.bindEnvironmentInfo(environmentInfo);
        this.service.bindUserAdmin(this.userAdmin.get());
        this.service.bindIdentityService(this.identityService);
    }
}
